import requests
from bs4 import BeautifulSoup

def scrape_data(url):
    headers = {
        'User-Agent': 'Mozilla/5.0 (compatible; MSIE 10.0; Windows NT 6.1; Trident/5.0)'
    }

    try:
        response = requests.get(url, headers=headers)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'html.parser')

        # Find all elements with class 'data-item'
        items = soup.find_all('data-item')

        # Extract values from each item
        for item in items:
            name = item.find('span', class_='name').get_text(strip=True)
            value = item.find('span', class_='value').get_text(strip=True)
            if name and value:
                yield {
                    'name': name,
                    'value': value
                }

        # Find all elements with class 'data-item'
        # ... repeat for all items...
    except Exception as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    url = 'https://example.com'
    data = scrape_data(url)
    for item in data:
        print(item)
